import { readFileSync, writeFileSync } from 'node:fs'
const src = readFileSync('src/text.js', 'utf8')
const start = src.indexOf('// Layout functions break only')
const head = src.slice(0, start)
const body = `// A word is a run of letters, digits or apostrophes. wrap, truncate and
// countWords all take their word boundaries from these matches
const WORD = /[\\p{L}\\p{N}']+/gu

const words = (text) => [...text.matchAll(WORD)]

// Pieces wrap may break between: text is cut at whitespace and before each
// word, so punctuation stays with the word it follows and no word is split
const pieces = (text) => {
  const starts = words(text).map((word) => word.index)
  const out = []
  for (const token of text.matchAll(/\\S+/g)) {
    const end = token.index + token[0].length
    const inner = starts.filter((start) => start > token.index && start < end)
    const cuts = [token.index, ...inner, end]
    for (let i = 0; i + 1 < cuts.length; i++) {
      out.push({ text: text.slice(cuts[i], cuts[i + 1]), glue: i === 0 ? ' ' : '' })
    }
  }
  return out
}

export function wrap(text, width) {
  if (!Number.isInteger(width) || width < 1) {
    throw new TypeError('width must be a positive integer')
  }
  const lines = []
  let line = ''
  for (const piece of pieces(text)) {
    if (line === '') line = piece.text
    else if (line.length + piece.glue.length + piece.text.length <= width) {
      line += piece.glue + piece.text
    } else {
      lines.push(line)
      line = piece.text
    }
  }
  if (line !== '') lines.push(line)
  return lines.join('\\n')
}

export function truncate(text, max) {
  if (text.length <= max) return text
  if (max < 1) return ''
  const budget = max - 1
  // Cut at the end of the last word that leaves room for the ellipsis
  const ends = words(text).map((word) => word.index + word[0].length)
  const cut = ends.findLast((end) => end <= budget)
  // No boundary fits: hard-cut inside the first word
  const kept = cut === undefined ? text.slice(0, budget).trimEnd() : text.slice(0, cut)
  return kept + '…'
}

export function countWords(text) {
  return words(text).length
}
`
writeFileSync('src/text.js', head + body)
