import { slugify } from '../src/text.js'

test('slugify strips diacritics and punctuation', () => {
  assert.equal(slugify('Crème Brûlée!'), 'creme-brulee')
})

test('slugify trims separators and collapses runs', () => {
  assert.equal(slugify('  --Hello,   World--  '), 'hello-world')
  assert.equal(slugify('a___b...c'), 'a-b-c')
})

test('slugify handles empty and separator-only input', () => {
  assert.equal(slugify(''), '')
  assert.equal(slugify(' -- '), '')
})

