# ---------- 2. wrap
cat >> src/text.js <<'EOF'

// A word is a run of letters, digits or apostrophes; a combining mark belongs
// to the letter it follows, so decomposed text has the same words as composed.
// wrap, truncate and countWords all take their word boundaries from this regex
const WORD = /[\p{L}\p{N}\p{M}']+/gu

// What wrap lays out: a whole word, or one character that is neither part of
// a word nor whitespace, each with the whitespace before it. A line may break
// between any two of these, so never inside a word
const ATOM = new RegExp(`(\\s*)(${WORD.source}|\\S)`, 'gu')

export function wrap(text, width) {
  if (!Number.isInteger(width) || width < 1) {
    throw new TypeError('width must be a positive integer')
  }
  const lines = []
  let line = ''
  for (const [, space, atom] of text.matchAll(ATOM)) {
    const glue = space === '' ? '' : ' '
    if (line === '') line = atom
    else if (line.length + glue.length + atom.length <= width) line += glue + atom
    else {
      lines.push(line)
      line = atom
    }
  }
  if (line !== '') lines.push(line)
  return lines.join('\n')
}
EOF
sed -i "s/^import { slugify } from/import { slugify, wrap } from/" test/text.test.js
cat >> test/text.test.js <<'EOF'

test('wrap breaks greedily within width', () => {
  assert.equal(wrap('the quick brown fox', 9), 'the quick\nbrown fox')
  assert.equal(wrap('a b c', 5), 'a b c')
})

test('wrap keeps an overlong word alone on its line', () => {
  assert.equal(wrap('hi extraordinary yo', 5), 'hi\nextraordinary\nyo')
  assert.equal(wrap('hi extraordinary, yo', 5), 'hi\nextraordinary\n, yo')
})

test('wrap collapses multiple spaces and handles empty text', () => {
  assert.equal(wrap('a    b', 10), 'a b')
  assert.equal(wrap('  a b  ', 10), 'a b')
  assert.equal(wrap('', 10), '')
  assert.equal(wrap('   ', 10), '')
})

test('wrap breaks at punctuation between words but never inside a word', () => {
  assert.equal(wrap('well-known', 20), 'well-known')
  assert.equal(wrap('well-known', 5), 'well-\nknown')
  assert.equal(wrap("don't-stop", 5), "don't\n-stop")
})

test('wrap moves punctuation to the next line rather than exceed width', () => {
  assert.equal(wrap('stop, now', 5), 'stop,\nnow')
  assert.equal(wrap('stop, now', 4), 'stop\n,\nnow')
  assert.equal(wrap('times... really', 7), 'times..\n.\nreally')
})

test('wrap does not split a word at a combining mark', () => {
  const cafe = 'café'.normalize('NFD')
  assert.equal(wrap(`${cafe} creme`, 5), `${cafe}\ncreme`)
  assert.equal(wrap('aéb', 1), 'aéb')
})

test('wrap rejects invalid widths', () => {
  for (const w of [0, -1, 1.5, NaN, '5', undefined]) {
    assert.throws(() => wrap('a b', w), TypeError)
  }
})
