const words = (text) => [...text.matchAll(WORD)]

export function truncate(text, max) {
  if (text.length <= max) return text
  if (max < 1) return ''
  const budget = max - 1
  // Cut at the end of the last word that leaves room for the ellipsis
  const ends = words(text).map((word) => word.index + word[0].length)
  const cut = ends.findLast((end) => end <= budget)
  if (cut !== undefined) return text.slice(0, cut) + '…'
  // No boundary fits: hard-cut, without leaving half a surrogate pair
  return text.slice(0, budget).replace(/[\uD800-\uDBFF]$/, '').trimEnd() + '…'
}
EOF
