test('truncate cuts at the last word boundary that fits', () => {
  assert.equal(truncate('hello world', 10), 'hello…')
  assert.equal(truncate('hello brave new world', 12), 'hello brave…')
  assert.equal(truncate('hello  world again', 8), 'hello…')
