test('truncate leaves no trailing whitespace before the ellipsis', () => {
  assert.equal(truncate('ab cd ef', 6), 'ab cd…')
  assert.equal(truncate('ab   cd', 5), 'ab…')
  assert.equal(truncate(' hello', 2), '…')
  assert.equal(truncate('   abc def', 3), '…')
  assert.equal(truncate('  abc def', 6), '  abc…')
