  const out = truncate('supercalifragilistic', 8)
  assert.equal(out, 'superca…')
  assert.ok(out.length <= 8)
  assert.equal(truncate('abc def', 1), '…')
  assert.equal(truncate('abc def', 0), '')
})

test('truncate keeps a combining mark with its word', () => {
  const cafe = 'café'.normalize('NFD')
  assert.equal(truncate(`${cafe} au lait`, 7), `${cafe}…`)
})

test('truncate does not split a surrogate pair when hard-cutting', () => {
  assert.equal(truncate('😀😀😀', 4), '😀…')
