test('countWords counts letters, digits and apostrophes', () => {
  assert.equal(countWords("don't stop 42 times"), 4)
  assert.equal(countWords('well-known, truly'), 3)
})

test('countWords returns 0 without words', () => {
  assert.equal(countWords(''), 0)
  assert.equal(countWords(' ... '), 0)
  assert.equal(countWords('  \n\t '), 0)
})

test('countWords counts decomposed and composed text alike', () => {
  const text = 'été à la crème'
  assert.equal(countWords(text.normalize('NFD')), countWords(text))
  assert.equal(countWords('été'.normalize('NFD')), 1)
})

test('wrap, truncate and countWords agree on words', () => {
  const text = "don't  stop, 42 times... well-known café".normalize('NFD')
  const total = countWords(text)
  assert.equal(total, 7)
  for (let width = 1; width <= text.length; width++) {
    const lines = wrap(text, width).split('\n')
    // Wrapping never splits or merges a word
    assert.equal(lines.reduce((sum, line) => sum + countWords(line), 0), total)
    for (const line of lines) {
      // Only a single word may be longer than width
      assert.ok(line.length <= width || /^[\p{L}\p{N}\p{M}']+$/u.test(line))
    }
  }
  for (let max = 1; max < text.length; max++) {
    const out = truncate(text, max)
    assert.ok(out.length <= max)
    assert.ok(text.startsWith(out.slice(0, -1)))
    // Where a word fits, the cut falls on a word end: the kept part and the
    // dropped part together hold exactly the words of the text
    const kept = out.slice(0, -1)
    if (countWords(kept) > 0 && max > "don't".length) {
      assert.equal(countWords(kept) + countWords(text.slice(kept.length)), total)
    }
  }
})
EOF
